from flask import Flask

app = Flask(__name__)


@app.route("/")
def index():
    return "OK"


def test_root_route_returns_200():
    client = app.test_client()
    response = client.get("/")
    assert response.status_code == 200


if __name__ == "__main__":
    test_root_route_returns_200()
    print("OK")
